<?php
declare(strict_types=1);
// Generates docs/TEST_REPORT.md from the recorded results of the last executed runs (never hand-edited).
$o = __DIR__ . '/output';
$unit = json_decode((string) file_get_contents("{$o}/results.json"), true);
$ui = is_file("{$o}/ui/ui-results.json") ? json_decode((string) file_get_contents("{$o}/ui/ui-results.json"), true) : [];
$perf = is_file("{$o}/perf.json") ? json_decode((string) file_get_contents("{$o}/perf.json"), true) : null;
$env = is_file("{$o}/environment.log") ? file_get_contents("{$o}/environment.log") : '';
$suites = [];
foreach ($unit['results'] as $r) {
    $suites[$r['suite']]['n'] = ($suites[$r['suite']]['n'] ?? 0) + 1;
    $suites[$r['suite']]['pass'] = ($suites[$r['suite']]['pass'] ?? 0) + ($r['ok'] ? 1 : 0);
}
$total = count($unit['results']);
$pass = count(array_filter($unit['results'], fn($r) => $r['ok']));
$uiPass = count(array_filter($ui, fn($r) => $r['ok']));
$md = "# EHF Volunteer Hub: Test Report\n\n> Generated by `php tests/report.php` from the recorded results of the last executed runs. Nothing in this file is hand-written.\n\n";
$md .= "| Item | Value |\n|---|---|\n| Run at (UTC) | {$unit['run_at']} |\n| PHP | {$unit['php']} |\n| Database | {$unit['db']} |\n";
$md .= "| Automated tests | **{$pass} / {$total} passed** |\n| Browser UI checks | **{$uiPass} / " . count($ui) . " passed** (desktop 1366px, tablet 820px, mobile 390px) |\n\n";
$md .= "## Automated tests by suite\n\n| Suite | Passed | Total |\n|---|---|---|\n";
foreach ($suites as $s => $c) { $md .= "| {$s} | {$c['pass']} | {$c['n']} |\n"; }
$md .= "\n## Every executed test\n\n| Suite | Test | Result | ms |\n|---|---|---|---|\n";
foreach ($unit['results'] as $r) { $md .= "| {$r['suite']} | " . str_replace('|', '/', $r['name']) . ' | ' . ($r['ok'] ? 'PASS' : '**FAIL** ' . str_replace('|', '/', $r['error'])) . " | {$r['ms']} |\n"; }
$md .= "\n## Browser UI checks\n\n";
$fails = array_filter($ui, fn($r) => !$r['ok']);
$md .= $fails ? "Failures:\n\n" . implode("\n", array_map(fn($r) => "- {$r['name']}: {$r['detail']}", $fails)) . "\n" : "All checks passed. Checks per page: no PHP error text; every form control labelled; no horizontal page overflow; images have alt text, one h1, lang=en; no browser console errors including CSP violations; sign-in and sign-out for each role; application submitted through the real form.\n";
if ($perf) {
    $md .= "\n## Performance (synthetic volume, local MariaDB; shared hosting will be slower)\n\nData: {$perf['rows']['v']} volunteers, {$perf['rows']['a']} activities, {$perf['rows']['t']} time logs, {$perf['rows']['att']} attendance rows, {$perf['audit_entries']} audit entries.\n\n";
    $md .= "| Measurement | Result |\n|---|---|\n| Audit writes (serialised hash chain) | {$perf['audit_writes_per_second']} per second |\n";
    foreach ($perf['ms'] as $k => $v) { $md .= "| {$k} | {$v} ms |\n"; }
    $md .= "| Audit verification result | {$perf['verify_result']} |\n";
}
$md .= "\n## Hosting compatibility probe (this development environment)\n\n```\n" . trim($env) . "\n```\n\nThe probe must be re-run on the exact Hostinger plan (and InfinityFree for staging) before installation. Host results are **not** verified here.\n";
$md .= "\n## Security test matrix ST-01 to ST-40 (Design Review Rev3 §8.3)\n\nEach case is an executed test in the `security` suite above. Documented interpretation: **ST-14** expects 404 for another volunteer's attendance; the implementation returns 403 for both cases because volunteers hold no attendance-write permission at all (§8.1 rule 9). The response is identical for every id, so nothing is disclosed. **ST-38** (audit archiving) is checked at permission level because archiving is a manual runbook (§6.11), not an application screen.\n";
@mkdir(dirname(__DIR__) . '/docs', 0755, true);
file_put_contents(dirname(__DIR__) . '/docs/TEST_REPORT.md', $md);
echo "docs/TEST_REPORT.md written: {$pass}/{$total} tests, {$uiPass}/" . count($ui) . " UI checks\n";
